一、算法思想
回文序列正读与反读相同，序列关于中心对称。利用栈“后进先出”的特性：先把字符串前一半字符依次入栈，再从中间位置开始，将后一半字符与栈顶元素逐一比较——相等则弹出栈顶继续比较，不等则可立即判定不是回文序列。比较结束后若栈为空，则为回文序列。

二、算法实现（C语言）

#define MAXSIZE 100

/* 判定字符串 s 是否为回文序列：是返回1，否返回0 */
int IsPalindrome(char *s)
{
    char stack[MAXSIZE];
    int top = -1;
    int len = strlen(s);
    int half = len / 2;
    int i;

    /* 1. 将前一半字符依次入栈 */
    for (i = 0; i < half; i++)
        stack[++top] = s[i];

    /* 2. 若长度为奇数，跳过中间的字符 */
    i = (len % 2 == 1) ? half + 1 : half;

    /* 3. 后一半字符与栈顶字符逐一比较 */
    while (i < len)
    {
        if (top < 0 || stack[top] != s[i])
            return 0;          /* 出现不同字符，不是回文 */
        top--;                 /* 相同则弹出栈顶 */
        i++;
    }
    return (top == -1) ? 1 : 0;
}

三、测试例
输入 "abba"  -> 输出：是回文序列
输入 "abdba" -> 输出：是回文序列
输入 "good"  -> 输出：不是回文序列

四、复杂度分析
时间复杂度 O(n)：每个字符至多入栈、出栈各一次，比较过程只扫描一遍字符串。
空间复杂度 O(n)：栈最多存放 n/2 个字符，n 为字符串长度。

五、说明
本算法只需扫描一遍字符串，且比较到第一个不相等字符即可提前返回，效率优于“将字符串逆置后与原串整体比较”的做法（后者需要完整扫描两次并额外存储整个串）。

一、存储结构设计
用带头结点的循环单链表表示队列，只设一个指针 rear 指向队尾元素结点。
由于是循环链表，有：
    rear->next          为头结点；
    rear->next->next    为队头元素结点（首元结点）。
这样仅用尾指针即可在 O(1) 时间内同时取得队头与队尾，入队、出队都不需要遍历链表。
队空条件：rear->next == rear，即头结点的 next 指向自身。

二、类型定义

typedef int ElemType;

typedef struct LNode {
    ElemType data;
    struct LNode *next;
} LNode, *LinkQueue;

三、初始化
void InitQueue(LinkQueue *rear)
{
    *rear = (LNode *)malloc(sizeof(LNode));  /* 建立头结点 */
    if (*rear == NULL) { printf("内存分配失败\n"); exit(1); }
    (*rear)->next = *rear;    /* 头结点自环，表示队列为空 */
}

四、入队
int EnQueue(LinkQueue *rear, ElemType x)
{
    LNode *s = (LNode *)malloc(sizeof(LNode));
    if (s == NULL) return 0;          /* 存储空间不足 */

    s->data = x;
    s->next = (*rear)->next;          /* 新结点指向头结点 */
    (*rear)->next = s;                /* 原队尾结点指向新结点 */
    *rear = s;                        /* rear 指向新的队尾元素 */
    return 1;
}

五、出队
int DeQueue(LinkQueue *rear, ElemType *x)
{
    if ((*rear)->next == *rear)       /* 队空 */
        return 0;

    LNode *head = (*rear)->next;      /* 头结点 */
    LNode *p = head->next;            /* p 指向队头元素结点 */

    *x = p->data;
    head->next = p->next;             /* 头结点越过 p，摘除队头结点 */

    if (p == *rear)                   /* 出队的是唯一元素，队列变空 */
        *rear = head;                 /* 尾指针重新指向头结点 */

    free(p);
    return 1;
}

六、完整测试程序
int main(void)
{
    LinkQueue rear;
    ElemType x;
    InitQueue(&rear);

    EnQueue(&rear, 10);
    EnQueue(&rear, 20);
    EnQueue(&rear, 30);

    while (DeQueue(&rear, &x))
        printf("%d ", x);   /* 输出：10 20 30 */
    printf("\n");
    return 0;
}

七、算法分析
1. 只设尾指针，通过 rear->next 和 rear->next->next 直接定位头结点与队头，入队、出队均为 O(1)，无需遍历链表。
2. 循环链表使尾指针能“绕回”表头，队头元素出队后无需移动其他元素。
3. 出队时必须判断“删除的是否为唯一元素”：若是，则须把 rear 重新指向头结点，否则 rear 会成为悬空指针，后续入队出错。
4. 队空条件 rear->next == rear 与“头结点自环”的初始化状态保持一致，逻辑统一。

一、顺序串类型定义

#define MAXLEN 255
typedef struct {
    char ch[MAXLEN];   /* 字符数组，存放串值 */
    int  length;       /* 串的当前长度 */
} SqString;

二、算法(1)：将串 r 中所有值为 ch1 的字符换成 ch2

void ReplaceChar(SqString *r, char ch1, char ch2)
{
    int i;
    for (i = 0; i < r->length; i++)
        if (r->ch[i] == ch1)      /* 找到待替换字符 */
            r->ch[i] = ch2;       /* 就地替换 */
}

算法思想：顺序串是随机存储结构，可按下标直接访问每个字符。
只需从头到尾扫描一遍，边扫描边修改，长度不变，无需额外空间。
时间复杂度 O(n)，空间复杂度 O(1)。

三、算法(2)：将串 r 中删除其值等于 ch 的字符

void DeleteChar(SqString *r, char ch)
{
    int i, k = 0;                  /* k 为写入位置 */
    for (i = 0; i < r->length; i++)
        if (r->ch[i] != ch)        /* 不是要删除的字符才保留 */
            r->ch[k++] = r->ch[i]; /* 前移覆盖 */
    r->length = k;                 /* 更新长度 */
}

算法思想：采用“双指针覆盖法”。i 为读指针，k 为写指针，
k 始终不大于 i，因此边扫描边把保留的字符前移不会覆盖尚未读取的字符。
扫描结束后 k 即为新串长度。
相比“每删一个字符就整体后移”的做法（O(n^2)），本算法只需一趟扫描，
时间复杂度 O(n)，空间复杂度 O(1)，且不破坏原串中保留字符的相对次序。

四、算法(3)：从串 r1 第 index 个字符起，求首次与 r2 相同的子串的起始位置

int IndexSub(SqString r1, SqString r2, int index)
{
    int i = index - 1;     /* 转换为 0 为起始的下标 */
    int j = 0;

    if (index < 1 || index > r1.length) return 0;  /* 位置非法 */
    if (r2.length == 0) return index;              /* 空串约定 */

    while (i < r1.length && j < r2.length)
    {
        if (r1.ch[i] == r2.ch[j]) { i++; j++; }    /* 继续比较后继字符 */
        else { i = i - j + 1; j = 0; }             /* 指针回退，重新开始 */
    }

    if (j >= r2.length)                            /* 匹配成功 */
        return i - r2.length + 1;                  /* 返回 1 为基准的起始位置 */
    return 0;                                      /* 未找到 */
}

算法思想：这是朴素的模式匹配（Brute-Force）算法。
从 r1 的第 index 个字符开始，与 r2 的第一个字符比较：
若相等则继续比较后续字符；若不等则主串指针回退到本趟起始位置的下一个字符，
模式串指针归零，重新开始下一趟比较。匹配成功时返回子串在主串中的起始位置
（以 1 为基准），否则返回 0 表示不存在。
时间复杂度 O(n*m)（n、m 分别为主串、模式串长度）；若改用 KMP 算法可降到 O(n+m)。

五、完整测试程序

int main(void)
{
    SqString r = {"hello world", 11};
    SqString r1 = {"ababcabcacbab", 13};
    SqString r2 = {"abcac", 5};
    int pos;

    ReplaceChar(&r, 'o', '0');
    printf("替换后: %.*s\n", r.length, r.ch);   /* hell0 w0rld */

    DeleteChar(&r, 'l');
    printf("删除后: %.*s\n", r.length, r.ch);   /* he0 w0rd */

    pos = IndexSub(r1, r2, 1);
    printf("首次出现位置: %d\n", pos);          /* 6 */

    pos = IndexSub(r1, r2, 8);
    printf("从第 8 位起查找: %d\n", pos);       /* 0，未找到 */
    return 0;
}

一、功能说明
StrReplace(S, T, V)：将串 S 中所有与串 T 相等的子串替换为串 V，
替换结果仍存放在 S 中。
由于 V 与 T 长度可能不同，替换后串长会发生变化，因此需要借助一个
临时顺序串 R 作为结果缓冲区，最后再回写到 S。

二、类型定义

#define MAXLEN 255
typedef struct {
    char ch[MAXLEN];
    int  length;
} SqString;

三、算法实现

int StrReplace(SqString *S, SqString T, SqString V)
{
    SqString R;                 /* 结果串缓冲区 */
    int i = 0, j, k, ok;

    if (T.length == 0) return 0;    /* 空模式串无意义，直接返回，避免死循环 */
    R.length = 0;

    while (i < S->length)
    {
        /* 1. 判断从下标 i 开始能否与 T 完全匹配 */
        ok = 1;
        if (i + T.length > S->length)
            ok = 0;                        /* 剩余长度不足 */
        else
            for (j = 0; j < T.length; j++)
                if (S->ch[i + j] != T.ch[j]) { ok = 0; break; }

        if (ok)                            /* 2. 匹配成功，换成 V */
        {
            if (R.length + V.length > MAXLEN) return 0;   /* 溢出保护 */
            for (k = 0; k < V.length; k++)
                R.ch[R.length++] = V.ch[k];
            i += T.length;                 /* 跳过已替换的 T */
        }
        else                               /* 3. 不匹配，保留原字符 */
        {
            if (R.length + 1 > MAXLEN) return 0;
            R.ch[R.length++] = S->ch[i++];
        }
    }

    *S = R;                                /* 结果回写 S */
    return 1;
}

四、算法思想
1. 从 S 的下标 0 开始，逐个位置尝试与 T 匹配。
2. 匹配成功时，把 V 整体追加到结果串 R 中，主串指针一次跳过 T.length 个字符；
3. 匹配失败时，把当前字符原样复制到 R，主串指针只前进 1 位。
   注意：不匹配时只前移 1 位而不是回退重扫，这是因为本算法是“顺序扫描 + 局部匹配”，
   已经确认过的字符不需要重新比较，因此效率优于逐位置暴力匹配。
4. 用独立缓冲区 R 避免“原地替换”时因长度变化造成的覆盖问题，
   最后一次性回写，保证 S 中未匹配部分的内容不丢失。

五、测试例

int main(void)
{
    SqString S = {"abcabcabc", 9};
    SqString T = {"bc", 2};
    SqString V = {"XYZ", 3};

    if (StrReplace(&S, T, V))
        printf("结果: %.*s\n", S.length, S.ch);   /* aXYZaXYZa */
    else
        printf("替换失败：结果串超长\n");

    SqString S2 = {"aaa", 3};
    SqString T2 = {"aa", 2};
    SqString V2 = {"b", 1};
    StrReplace(&S2, T2, V2);
    printf("结果: %.*s\n", S2.length, S2.ch);     /* ba */
    return 0;
}

六、复杂度分析
设 S、T、V 的长度分别为 n、m、p。
最坏情况下每个位置都要比较 m 个字符，时间开销为 O(n*m) 次字符比较；
每复制一个字符进 R 是 O(1) 操作，复制总量不超过 O(n + (n/m)*p)。
空间复杂度 O(n + (n/m)*p)，即结果串的最大长度，用顺序串缓冲区实现。
若改用 KMP 求 next 数组进行匹配，可把时间降到 O(n + m)。

一、鞍点定义
矩阵元素 A[i][j] 若满足：它是第 i 行中值最小的元素，同时又是第 j 列中值最大的元素，
则称 A[i][j] 为该矩阵的一个鞍点。
注意：一个矩阵可能没有鞍点，也可能有多个鞍点。

二、算法设计思路
分两步进行：
第一步：逐行扫描，求出第 i 行的最小值 minVal 及其所在列号 minCol；
第二步：沿 minCol 这一列向上向下扫描，检查 minVal 是否是该列的最大值；
        若是，则 A[i][minCol] 即为鞍点，输出之；否则该行无鞍点。
为避免“一行中有多个相同的最小值”而漏解，需把该行中所有等于 minVal 的列都
分别验证一遍（见下面完整代码）。

三、算法实现（C语言，矩阵为 M 行 N 列）

#define M 10
#define N 10

void FindSaddle(int A[M][N])
{
    int i, j, k, c;
    int minVal, isSaddle, found = 0;

    for (i = 0; i < M; i++)
    {
        /* 第一步：求第 i 行的最小值 */
        minVal = A[i][0];
        for (j = 1; j < N; j++)
            if (A[i][j] < minVal)
                minVal = A[i][j];

        /* 第二步：对该行所有等于最小值的列逐一检验 */
        for (c = 0; c < N; c++)
        {
            if (A[i][c] != minVal) continue;

            isSaddle = 1;
            for (k = 0; k < M; k++)          /* 同列中是否有更大的元素 */
                if (A[k][c] > minVal) { isSaddle = 0; break; }

            if (isSaddle)
            {
                printf("鞍点: A[%d][%d] = %d\n", i, c, minVal);
                found = 1;
            }
        }
    }

    if (!found) printf("该矩阵没有鞍点\n");
}

四、测试例
A = { { 9,  7,  6,  8 },
      { 20, 26, 22, 25 },
      { 28, 36, 25, 30 },
      { 12, 14, 15, 16 } }
第 0 行最小值 6 在第 2 列，第 2 列元素为 6、22、25、15，最大值 25 ≠ 6，第 0 行无鞍点；
第 1 行最小值 20 在第 0 列，第 0 列最大值为 28 ≠ 20；
第 2 行最小值 25 在第 2 列，第 2 列最大值为 25，故 A[2][2] = 25 是鞍点；
第 3 行最小值 12 在第 0 列，第 0 列最大值 28 ≠ 12。
输出：鞍点: A[2][2] = 25

五、复杂度分析
求每行最小值需 O(N)，每行最多验证 N 个候选列，每个候选列需 O(M)，
最坏情况下每行验证 N 次，故总时间 O(M*N + M*N*M) = O(M^2 * N)。
常见教材给出的简化版本（每行只取第一个最小值、只验证一次）时间复杂度为 O(M*N)；
若采用“预先把每列最大值求出来缓存”的优化做法，可把总时间降为 O(M*N)：
先花 O(M*N) 求出各列最大值存于数组 colMax[N]，再逐行求最小值并直接与 colMax[minCol] 比较，
整体只需两趟扫描。
空间复杂度 O(1)（简化版）或 O(N)（缓存列最大值版）。

一、问题分析
数组 A[1..n]，要求把每个元素循环右移 k 位，即：
    A'[i] = A[(i - k - 1 + n) % n + 1]
要求只使用一个元素大小的辅助空间（即空间复杂度 O(1)），并给出时间复杂度。

若采用“右移一位、重复 k 次”的朴素做法，每次都要把末尾元素暂存再整体后移，
时间为 O(k*n)，当 k 接近 n 时退化为 O(n^2)，效率低。

二、算法思想：三次逆置法
设数组分为前后两段：左段 L = A[1..n-k]，右段 R = A[n-k+1..n]。
循环右移 k 位，等价于把数组看成 R 和 L 两部分并交换位置，即 LR -> RL。
利用“逆置”这一基本操作（只需一个中间变量即可原地完成）：
    逆置(L) 逆置(R) 逆置(整体) = (L^R)(R^R) 再整体逆置 = RL
具体三步：
    第 1 步：逆置 A[1 .. n-k]      得 L^R
    第 2 步：逆置 A[n-k+1 .. n]    得 R^R
    第 3 步：逆置 A[1 .. n]        整体逆置，得到 RL，即循环右移 k 位的结果

三、算法实现（C语言，下标从 1 开始）

/* 逆置 A[left..right]，只用 1 个辅助变量 */
void Reverse(int A[], int left, int right)
{
    int t;
    while (left < right)
    {
        t = A[left];
        A[left] = A[right];
        A[right] = t;
        left++;
        right--;
    }
}

/* 将 A[1..n] 循环右移 k 位 */
void RotateRight(int A[], int n, int k)
{
    if (n <= 1) return;
    k = k % n;              /* k 可能大于 n，取模后等价 */
    if (k == 0) return;     /* 移动 n 的整数倍，相当于不变 */

    Reverse(A, 1, n - k);       /* 第 1 步：逆置左段 */
    Reverse(A, n - k + 1, n);   /* 第 2 步：逆置右段 */
    Reverse(A, 1, n);           /* 第 3 步：整体逆置 */
}

四、正确性验证
例：A = {1, 2, 3, 4, 5}（下标 1..5），n = 5，k = 2
第 1 步 Reverse(A,1,3)：{3, 2, 1, 4, 5}
第 2 步 Reverse(A,4,5)：{3, 2, 1, 5, 4}
第 3 步 Reverse(A,1,5)：{4, 5, 1, 2, 3}
结果 {4,5,1,2,3} 正是把 {1,2,3,4,5} 循环右移 2 位，正确。

再例：k = 0 -> 直接返回，数组不变；k = 5 -> 5 % 5 = 0，数组不变，符合定义。

五、复杂度分析
时间复杂度 O(n)：
    第 1 步逆置 n-k 个元素，第 2 步逆置 k 个元素，第 3 步逆置 n 个元素，
    每个元素每次只参与一次交换，总交换次数为 (n-k)/2 + k/2 + n/2 = n，
    即总共约 n 次交换、2n 次赋值，与 k 无关，故为 O(n)。
空间复杂度 O(1)：
    只使用了一个中间变量 t，满足“只用一个元素大小的辅助空间”的要求。

六、与其他解法比较
1. 逐位右移法：时间 O(k*n)，空间 O(1)，k 大时效率差。
2. 辅助数组法：时间 O(n)，空间 O(n)，不满足题目空间要求。
3. 三次逆置法（本解）：时间 O(n)，空间 O(1)，同时满足时间与空间的最优要求，是最简洁经典的解法。

一、存储结构
用邻接矩阵存储图，G->edges[i][j] 为 1 表示顶点 i 到 j 有边（有向图）或 i、j 相邻（无向图），为 0 表示无边。

#define MAXV 100
typedef struct {
    int edges[MAXV][MAXV];   /* 邻接矩阵 */
    int n;                   /* 顶点个数 */
} MGraph;

int visited[MAXV];           /* 访问标志数组 */

二、算法思想
判断顶点 u 到顶点 w 之间是否存在路径，本质上是判断从 u 出发做一次
深度优先搜索（或广度优先搜索）能否到达 w。
从 u 出发沿邻接矩阵逐列扫描：若 u 的第 j 列非 0 且 j 未被访问，则递归进入 j；
一旦递归到 w 就立即返回 1；若所有可达顶点都搜索完毕仍未遇到 w，返回 0。
搜索前必须把 visited 数组清零，保证多次调用互不影响。

三、深度优先搜索实现

/* 从顶点 v 出发深度优先搜索，判断能否到达 dest */
int DFSReach(MGraph *G, int v, int dest)
{
    int i;
    if (v == dest) return 1;          /* 已到达目标顶点 */

    visited[v] = 1;                   /* 标记已访问，防止死循环 */

    for (i = 0; i < G->n; i++)
        if (G->edges[v][i] != 0 && !visited[i])
            if (DFSReach(G, i, dest))
                return 1;             /* 只要有一条分支能到达就成立 */

    return 0;
}

/* 对外接口：判断 u 与 w 之间是否存在路径 */
int HasPath(MGraph *G, int u, int w)
{
    int i;
    if (u < 0 || u >= G->n || w < 0 || w >= G->n) return 0;  /* 顶点号非法 */

    for (i = 0; i < G->n; i++)
        visited[i] = 0;               /* 每调用一次都重新初始化 */

    return DFSReach(G, u, w);
}

四、等价的广度优先搜索实现

int HasPathBFS(MGraph *G, int u, int w)
{
    int queue[MAXV], front = 0, rear = 0;
    int i, v;

    if (u < 0 || u >= G->n || w < 0 || w >= G->n) return 0;
    for (i = 0; i < G->n; i++) visited[i] = 0;

    visited[u] = 1;
    queue[rear++] = u;                 /* 起点入队 */

    while (front < rear)
    {
        v = queue[front++];            /* 出队 */
        if (v == w) return 1;          /* 找到目标 */

        for (i = 0; i < G->n; i++)
            if (G->edges[v][i] != 0 && !visited[i])
            {
                visited[i] = 1;
                queue[rear++] = i;     /* 邻接点入队 */
            }
    }
    return 0;                          /* 搜索完所有可达顶点仍未找到 */
}

五、正确性说明
1. visited 数组保证每个顶点至多被访问一次，不会因图中存在回路而死循环；
2. DFS 只要某条分支能到达 w 就立即返回 1，不会漏掉通路；
3. 若 u == w，按“自身到自身存在长度为 0 的路径”约定返回 1（DFS 第一行即返回）。
   若课程要求 u == w 时返回 0，只需在 HasPath 开头加一个 u == w 的判断即可。

六、复杂度分析
时间：DFS/BFS 最坏要检查矩阵的每个元素，O(n^2)，n 为顶点数；
空间：visited 数组 O(n)，DFS 递归栈最深 O(n)，BFS 队列 O(n)。
若改用邻接表存储，时间复杂度可降为 O(n + e)。
